<?php require_once __DIR__.'/../includes/functions.php';role('teacher');$id=$_SESSION['user_id'];$s=$conn->prepare('SELECT * FROM courses WHERE teacher_id=? ORDER BY title');$s->bind_param('i',$id);$s->execute();$rows=$s->get_result();$page_title='My Courses';include __DIR__.'/../includes/header.php';?><h1>My Courses</h1><p><a class="btn" href="<?=BASE_URL?>/teacher/create_course.php">+ Create course</a></p><div class="grid"><?php while($c=$rows->fetch_assoc()):?><div class="card"><p class="eyebrow">COURSE</p><h2><?=e($c['subject_code']?:$c['title'])?></h2><p><?=e($c['subject_description']?:$c['description'])?></p><?php if($c['units']!==null):?><p class="muted"><?=e($c['units'])?> units · <?=e(schedule_label($c['schedule_days']??'',$c['schedule_times']??'',$c['schedule_date']??'',$c['schedule_time']??''))?></p><?php endif;?><a class="btn" href="<?=BASE_URL?>/teacher/course.php?id=<?=$c['id']?>">Manage course</a></div><?php endwhile;?></div><?php include __DIR__.'/../includes/footer.php';?>
